import sys
import xml.etree.ElementTree as ET
from collections import deque

def parse_xml_config(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    max_concurrency = int(root.get('max-concurrency'))
    rules = []
    for rule in root.findall('rule'):
        name = rule.get('name')
        expr = rule.get('expr')
        rules.append((name, expr))
    return max_concurrency, rules

def evaluate_expression(expr, variables):
    try:
        return eval(expr, {}, variables)
    except:
        return 0

def process_input(max_concurrency, rules, input_lines):
    queue = deque()
    output_queue = deque()
    current_lines = 0
    current_output = 0

    for line in input_lines:
        if current_lines >= max_concurrency:
            output_queue.append(line)
            continue

        tokens = line.strip().split()
        variables = {}
        for token in tokens:
            key, value = token.split('=')
            variables[key] = int(value)

        results = []
        for name, expr in rules:
            result = evaluate_expression(expr, variables)
            results.append(f"{name}={result}")

        output = ' '.join(results)
        queue.append(output)
        current_lines += 1

    while queue:
        output = queue.popleft()
        output_queue.append(output)
        current_lines -= 1

    return output_queue

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_path = sys.argv[1]
    max_concurrency, rules = parse_xml_config(xml_path)

    input_lines = sys.stdin.read().splitlines()
    output_lines = process_input(max_concurrency, rules, input_lines)

    for line in output_lines:
        print(line)

if __name__ == "__main__":
    main()

