import sys
import xml.etree.ElementTree as ET
from concurrent.futures import ThreadPoolExecutor, as_completed
from collections import deque

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    max_concurrency = int(root.attrib['max-concurrency'])
    rule = root.find('rule')
    return max_concurrency, rule.attrib['name'], rule.attrib['expr']

def evaluate_expression(expr, w, h):
    try:
        return eval(expr, {'w': w, 'h': h}, {})
    except:
        return 0

def process_line(line, rule_name, expr):
    w, h = map(int, line.split()[1:3])
    result = evaluate_expression(expr, w, h)
    return f"{rule_name}={result}"

def main():
    xml_path = sys.argv[1]
    max_concurrency, rule_name, expr = parse_xml(xml_path)
    input_lines = deque()

    with ThreadPoolExecutor(max_workers=max_concurrency) as executor:
        futures = []
        for line in sys.stdin:
